/**
 * struct dw_spi – core DW APB SSI private state.
 * Mirrors the upstream struct dw_spi from spi-dw.h.
 */
struct dw_spi {
    uintptr_t   base;           /* bind.state: dev->base */
    uintptr_t   paddr;          /* physical address */
    uint32_t    irq;            /* logical IRQ number */
    uint32_t    fifo_len;       /* depth of the TX FIFO */
    uint32_t    rx_fifo_len;    /* depth of the RX FIFO (for enhanced mode) */
    uint32_t    max_freq;       /* max bus frequency (Hz) */
    uint32_t    current_freq;   /* current operating frequency */
    uint32_t    num_cs;          /* number of chip-selects */
    uint32_t    reg_width;      /* register access width: 1, 2, or 4 */

    /* Configuration mirrors */
    uint32_t    ctrlr0;          /* cached CTRLR0 */
    uint32_t    ctrlr1;          /* cached CTRLR1 (nframes in non-stream mode) */
    uint32_t    txftlr;          /* cached TXFTLR */
    uint32_t    rxftlr;          /* cached RXFTLR */
    uint32_t    baudr;          /* cached BAUDR divider */
    uint32_t    imr;             /* cached IMR interrupt mask */

    /* Transfer state */
    const uint8_t  *tx;          /* next TX byte to send */
    uint32_t        tx_len;      /* remaining TX bytes */
    uint8_t        *rx;          /* next RX destination byte */
    uint32_t        rx_len;      /* remaining RX slots */
    uint32_t        rx_to_read;  /* bytes still expected to read */
    uint32_t        n_bytes;     /* bytes per SPI frame: 1, 2, or 4 */
    uint32_t        tmode;      /* transfer mode bits */
    uint32_t        dws_version; /* VERSION register value */
    uint32_t        def_mode;    /* default SPI mode bits */

    /* Enhanced / extended mode */
    uint32_t    csgpo;          /* CS GPIO override value */
    uint32_t    enhanced_spi_mode; /* flag for enhanced mode */
    uint32_t    rx_sample_delay; /* RX_SAMPLE_DLY value */
    uint32_t    cs_override;     /* CS_OVERRIDE value */

    /* Chip-select override (MSCC / Sparx5 / Elba variants) */
    uint32_t    cs_override_val;

    /* Role flags */
    uint32_t    target_abort;
    uint32_t    driver_cleanup;

    /* Error stats */
    uint32_t    rx_overrun;
    uint32_t    tx_overrun;
    uint32_t    rx_underrun;
    uint32_t    tx_underrun;
};

